def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    def gen():
        elements = iter(iterable)
        last_value = next(elements, sentinel)
        for value in elements:
            if key is None:
                if value != last_value:
                    yield last_value
                    last_value = value
            else:
                if key(value) != key(last_value):
                    yield last_value
                    last_value = value
        yield last_value

    sentinel = object()
    return gen()

